-- LGS Cosmetics core schema for Hostinger MySQL/MariaDB.

-- Import into a newly created, empty database selected in phpMyAdmin.

-- Contains table structure only; no customer/order/review/admin data or credentials.

-- Better Auth customer tables are created by the app during its first successful startup.

SET NAMES utf8mb4;

SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE IF NOT EXISTS `admins` (`id` INTEGER NOT NULL auto_increment , `name` VARCHAR(120) NOT NULL, `email` VARCHAR(180) NOT NULL UNIQUE, `passwordHash` VARCHAR(255) NOT NULL, `role` VARCHAR(50) NOT NULL DEFAULT 'Super Admin', `status` VARCHAR(20) NOT NULL DEFAULT 'Active', `lastLoginAt` DATETIME, `token_version` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `product_categories` (`id` INTEGER NOT NULL auto_increment , `name` VARCHAR(150) NOT NULL, `slug` VARCHAR(180) NOT NULL UNIQUE, `description` TEXT, `image` VARCHAR(255), `group` VARCHAR(50), `types` JSON, `status` VARCHAR(20) NOT NULL DEFAULT 'Active', `displayOrder` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `products` (`id` INTEGER NOT NULL auto_increment , `name` VARCHAR(180) NOT NULL, `slug` VARCHAR(220) NOT NULL UNIQUE, `brand` VARCHAR(120), `type` VARCHAR(120), `subtitle` VARCHAR(220), `description` TEXT, `short_description` TEXT, `price` DECIMAL(10,2) NOT NULL DEFAULT 0, `sale_price` DECIMAL(10,2), `sku` VARCHAR(100), `stock` INTEGER NOT NULL DEFAULT 0, `shipping_weight_grams` INTEGER, `shipping_length_cm` INTEGER, `shipping_width_cm` INTEGER, `shipping_height_cm` INTEGER, `main_image` VARCHAR(255), `additional_images` JSON, `status` VARCHAR(20) NOT NULL DEFAULT 'Active', `featured` TINYINT(1) NOT NULL DEFAULT false, `ingredients` TEXT, `benefits` TEXT, `usage` TEXT, `size` VARCHAR(120), `variants` JSON, `tags` JSON, `rating` DECIMAL(3,1), `reviews` INTEGER, `meta_title` VARCHAR(180), `meta_description` TEXT, `category_id` INTEGER NOT NULL, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`category_id`) REFERENCES `product_categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `product_images` (`id` INTEGER NOT NULL auto_increment , `product_id` INTEGER NOT NULL, `url` VARCHAR(255) NOT NULL, `alt` VARCHAR(180), `is_primary` TINYINT(1) NOT NULL DEFAULT false, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `blog_categories` (`id` INTEGER NOT NULL auto_increment , `name` VARCHAR(150) NOT NULL, `slug` VARCHAR(180) NOT NULL UNIQUE, `description` TEXT, `status` VARCHAR(20) NOT NULL DEFAULT 'Active', `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `blogs` (`id` INTEGER NOT NULL auto_increment , `title` VARCHAR(220) NOT NULL, `slug` VARCHAR(240) NOT NULL UNIQUE, `excerpt` TEXT, `content` LONGTEXT, `featured_image` VARCHAR(255), `author` VARCHAR(120), `tags` JSON, `status` VARCHAR(20) NOT NULL DEFAULT 'Draft', `published_at` DATETIME, `meta_title` VARCHAR(180), `meta_description` TEXT, `category_id` INTEGER, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`category_id`) REFERENCES `blog_categories` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `orders` (`id` INTEGER NOT NULL auto_increment , `order_number` VARCHAR(50) NOT NULL UNIQUE, `customer_id` VARCHAR(64), `checkout_key` VARCHAR(100) UNIQUE, `customer_name` VARCHAR(120) NOT NULL, `email` VARCHAR(180), `phone` VARCHAR(50), `shipping_address` TEXT, `billing_address` TEXT, `subtotal` DECIMAL(10,2) NOT NULL DEFAULT 0, `discount` DECIMAL(10,2) NOT NULL DEFAULT 0, `shipping_charge` DECIMAL(10,2) NOT NULL DEFAULT 0, `total_amount` DECIMAL(10,2) NOT NULL DEFAULT 0, `payment_method` VARCHAR(50), `payment_status` VARCHAR(20) NOT NULL DEFAULT 'Pending', `order_status` VARCHAR(20) NOT NULL DEFAULT 'Pending', `notes` TEXT, `delivery_mode` VARCHAR(20) NOT NULL DEFAULT 'Delivery', `coupon_code` VARCHAR(60), `gateway_order_id` VARCHAR(100) UNIQUE, `payment_reference` VARCHAR(100), `courier_name` VARCHAR(100), `tracking_number` VARCHAR(150), `tracking_url` VARCHAR(1000), `stock_released` TINYINT(1) NOT NULL DEFAULT false, `shipping_provider` VARCHAR(30), `shipment_state` VARCHAR(30), `shipping_details` JSON, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `order_items` (`id` INTEGER NOT NULL auto_increment , `order_id` INTEGER NOT NULL, `product_id` INTEGER, `product_name` VARCHAR(180) NOT NULL, `product_image` VARCHAR(255), `variant_label` VARCHAR(120), `price` DECIMAL(10,2) NOT NULL DEFAULT 0, `quantity` INTEGER NOT NULL DEFAULT 1, `total` DECIMAL(10,2) NOT NULL DEFAULT 0, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `contact_enquiries` (`id` INTEGER NOT NULL auto_increment , `name` VARCHAR(120) NOT NULL, `email` VARCHAR(180), `phone` VARCHAR(50), `subject` VARCHAR(180), `message` TEXT NOT NULL, `status` VARCHAR(20) NOT NULL DEFAULT 'New', `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `coupons` (`id` INTEGER NOT NULL auto_increment , `code` VARCHAR(60) NOT NULL UNIQUE, `discount_type` VARCHAR(20) NOT NULL DEFAULT 'percentage', `discount_value` DECIMAL(10,2) NOT NULL, `min_order_amount` DECIMAL(10,2) NOT NULL DEFAULT 0, `max_discount` DECIMAL(10,2), `status` VARCHAR(20) NOT NULL DEFAULT 'Active', `expires_at` DATETIME, `usage_limit` INTEGER, `used_count` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `instagram_posts` (`id` INTEGER NOT NULL auto_increment , `image` VARCHAR(255) NOT NULL, `caption` VARCHAR(255), `link` VARCHAR(500), `sort_order` INTEGER NOT NULL DEFAULT 0, `is_active` TINYINT(1) NOT NULL DEFAULT true, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `site_settings` (`key` VARCHAR(100) , `value` JSON NOT NULL, `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `reviews` (`id` INTEGER NOT NULL auto_increment , `reviewer_name` VARCHAR(150) NOT NULL, `rating` INTEGER NOT NULL, `text` TEXT NOT NULL, `review_url` VARCHAR(1000), `source` VARCHAR(30) NOT NULL DEFAULT 'Google', `is_excerpt` TINYINT(1) NOT NULL DEFAULT false, `is_translated` TINYINT(1) NOT NULL DEFAULT false, `status` VARCHAR(20) NOT NULL DEFAULT 'Published', `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `order_events` (`id` INTEGER NOT NULL auto_increment , `order_id` INTEGER NOT NULL, `order_status` VARCHAR(30) NOT NULL, `payment_status` VARCHAR(40) NOT NULL, `note` VARCHAR(1000) NOT NULL, `createdAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `order_emails` (`id` INTEGER NOT NULL auto_increment , `event_id` INTEGER NOT NULL UNIQUE, `order_id` INTEGER NOT NULL, `recipient` VARCHAR(180) NOT NULL, `payload` JSON NOT NULL, `status` VARCHAR(20) NOT NULL DEFAULT 'Queued', `attempts` INTEGER NOT NULL DEFAULT 0, `last_error` TEXT, `first_attempt_at` DATETIME, `sent_at` DATETIME, `next_attempt_at` DATETIME, `provider_id` VARCHAR(180), `createdAt` DATETIME NOT NULL, `updatedAt` DATETIME NOT NULL, PRIMARY KEY (`id`), FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET FOREIGN_KEY_CHECKS=1;
